DROP TABLE IF EXISTS T CASCADE;
CREATE TABLE T(rid SERIAL, c0 INTEGER NOT NULL,c1 INTEGER NOT NULL,c2 INTEGER,c3 INTEGER,c4 INTEGER,c5 INTEGER,c6 INTEGER,c7 INTEGER);
CREATE UNIQUE INDEX k0_0 ON T(c1,c2) WHERE c2 IS NOT NULL;
CREATE UNIQUE INDEX k0_1 ON T(c1) WHERE c2 IS NULL;
CREATE OR REPLACE FUNCTION chk_k0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c2 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  IF (NEW.c2 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k0 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k0();
